# -*- coding: utf-8 -*-
"""kb_tags.py — 标签词表审计：把「标签失控」变成可测量的数字。

为什么需要它
------------
2026-10-04 实测：全库 **1,566** 个不同标签，其中 **1,107 个（70%）只出现过一次**。
标签的检索价值来自**复用**——一次性标签等价于自由文本，对聚类/筛选/图谱着色
贡献为零，却让词表膨胀到无法浏览。

而这个问题此前**不可见**：没有任何工具报告过标签规模，所以它只会单向恶化。
本工具让「一次性标签占比」成为一个可以定期看、可以设阈值、可以追责的数字。

用法
----
    python tools/kb_tags.py --stats        # 规模、分布、变体组
    python tools/kb_tags.py --suggest      # 可直接合并的拼写变体
    python tools/kb_tags.py --lowuse 2     # 列出只用了 N 次及以下的标签
    python tools/kb_tags.py --json
    python tools/kb_tags.py --selftest
"""

import os
import sys
import json
import argparse
import collections

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K

# 词表健康阈值：一次性标签占比超过此值即告警
SINGLETON_WARN = 0.60


def norm(t):
    """归一化：小写 + 去连字符/下划线/空格。用于发现拼写变体。"""
    return t.lower().replace("-", "").replace("_", "").replace(" ", "")


def parse_tags(text):
    """从页面文本取标签列表（容错 str / list 两种写法）。"""
    fm = K.parse_frontmatter(K.split_frontmatter(text)[0])
    ts = fm.get("tags") or []
    if isinstance(ts, str):
        ts = [t.strip() for t in ts.strip("[]").split(",")]
    out = []
    for t in ts:
        t = str(t).strip().strip("\"'")
        if t:
            out.append(t)
    return out


def collect():
    cnt = collections.Counter()
    bytype = collections.defaultdict(collections.Counter)
    where = collections.defaultdict(list)
    for d in K.PAGE_DIRS:
        p = os.path.join(K.WIKI, d)
        if not os.path.isdir(p):
            continue
        for f in sorted(os.listdir(p)):
            if not f.endswith(".md"):
                continue
            for t in parse_tags(K.read_text(os.path.join(p, f))):
                cnt[t] += 1
                bytype[d][t] += 1
                where[t].append("%s/%s" % (d, f[:-3]))
    return cnt, bytype, where


def variant_groups(cnt):
    """归一化后相同 ⇒ 仅大小写/连字符差异，合并无语义损失。"""
    g = collections.defaultdict(list)
    for t, c in cnt.items():
        g[norm(t)].append((t, c))
    out = [(k, sorted(v, key=lambda x: (-x[1], x[0])))
           for k, v in g.items() if len(v) > 1]
    out.sort(key=lambda kv: (-sum(c for _, c in kv[1]), kv[0]))
    return out


def stats():
    cnt, bytype, where = collect()
    total = sum(cnt.values())
    distinct = len(cnt)
    single = sum(1 for v in cnt.values() if v == 1)
    core5 = sum(1 for v in cnt.values() if v >= 5)
    vg = variant_groups(cnt)
    ratio = single / distinct if distinct else 0.0
    d = {
        "distinct_tags": distinct,
        "total_refs": total,
        "singleton_tags": single,
        "singleton_ratio": round(ratio, 3),
        "tags_ge5": core5,
        "variant_groups": len(vg),
        "variant_wasted_refs": sum(sum(c for _, c in v[1]) for v in vg),
        "pages": sum(1 for d2 in K.PAGE_DIRS
                     for f in (os.listdir(os.path.join(K.WIKI, d2))
                               if os.path.isdir(os.path.join(K.WIKI, d2)) else [])
                     if f.endswith(".md")),
        "by_type": {k: {"distinct": len(v), "refs": sum(v.values())}
                    for k, v in bytype.items()},
    }
    d["healthy"] = ratio <= SINGLETON_WARN
    return d, cnt, where, vg


def selftest():
    print("=== kb_tags --selftest ===")
    ok = True
    # 1) 解析：list 与 str 两种写法都要能读
    cases = [
        ("---\ntags: [a, b]\n---\n正文", ["a", "b"], "list 写法"),
        ("---\ntags: a, b\n---\n正文", ["a", "b"], "纯标量写法"),
        ("---\ntags: []\n---\n正文", [], "空列表"),
        ("---\ntype: source\n---\n正文", [], "无 tags 字段"),
        ('---\ntags: ["a", \'b\']\n---\n正文', ["a", "b"], "带引号项"),
    ]
    for txt, want, name in cases:
        got = parse_tags(txt)
        good = got == want
        print("  [%s] 解析 %s -> %s" % ("ok" if good else "FAIL", name, got))
        ok = ok and good
    # 2) 归一化：大小写/连字符变体必须归到同一键
    for a, b, same in [("LLM", "llm", True), ("multi-modal", "multimodal", True),
                       ("anti-site-defect", "antisite-defect", True),
                       ("GNN", "gnn", True), ("LLM", "GNN", False)]:
        good = (norm(a) == norm(b)) is same
        print("  [%s] 归一化 %s ~ %s -> %s（期望同键=%s）"
              % ("ok" if good else "FAIL", a, b, norm(a) == norm(b), same))
        ok = ok and good
    # 3) 变体发现：构造反例，不得把真正不同的标签并成一组
    fake = collections.Counter({"LLM": 3, "llm": 1, "GNN": 2, "transformer": 4})
    vg = variant_groups(fake)
    # ⚠️ vg 的元素是 (归一化键, [(标签, 次数), ...])——
    #    取「保留标签」必须走 v[1][0][0]；写成 v[0][0] 会拿到归一化键的**首字符**
    #    （本 selftest 初版正是这么写的，于是断言恒假而报 FAIL）。
    keys = [v[1][0][0] for v in vg]
    good = ("LLM" in keys) and ("GNN" not in keys)
    print("  [%s] 变体发现 LLM/llm 成组、GNN 单独不成组 -> %s"
          % ("ok" if good else "FAIL", [(" | ".join("%s(%d)" % x for x in v)) for _, v in vg]))
    ok = ok and good
    # 4) 变体组内保留项必须是引用最多的那个
    good = all(v[0][1] == max(c for _, c in v) for _, v in vg)
    print("  [%s] 每组「建议保留」均为引用最多者" % ("ok" if good else "FAIL"))
    ok = ok and good
    print("=== selftest %s ===" % ("PASS" if ok else "FAIL"))
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="标签词表审计")
    ap.add_argument("--stats", action="store_true")
    ap.add_argument("--suggest", action="store_true")
    ap.add_argument("--lowuse", type=int, default=0)
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    d, cnt, where, vg = stats()

    if args.json:
        print(json.dumps({"stats": d,
                          "variant_groups": [{"keep": v[0][0],
                                              "drop": [t for t, _ in v[1:]],
                                              "refs": sum(c for _, c in v)}
                                             for _, v in vg]},
                         ensure_ascii=False, indent=1))
        return 0

    if args.lowuse:
        low = [(t, c) for t, c in cnt.items() if c <= args.lowuse]
        low.sort(key=lambda kv: kv[1])
        print("标签引用 ≤%d 次的共 %d 个（占不同标签的 %d%%）："
              % (args.lowuse, len(low), len(low) * 100 // max(1, d["distinct_tags"])))
        for t, c in low[:80]:
            print("  %2d  %s" % (c, t))
        if len(low) > 80:
            print("  … 另有 %d 个" % (len(low) - 80))
        return 0

    if args.suggest:
        print("=== 可直接机械合并的拼写变体（%d 组）===" % len(vg))
        for _, v in vg:
            keep = v[0]
            drop = ", ".join("%s(%d)" % (t, c) for t, c in v[1:])
            print("  保留 %-28s  合并 %-40s  合计 %d"
                  % (keep[0], drop, sum(c for _, c in v)))
        print("\n（合并前先跑 python tools/qc_same_text.py \"<旧标签>\" 定位全部副本）")
        return 0

    # 默认输出 --stats
    print("=== 标签词表健康度 ===")
    print("  不同标签      : %d" % d["distinct_tags"])
    print("  引用总数      : %d" % d["total_refs"])
    print("  一次性标签    : %d（%.0f%%）阈值 %.0f%%  -> %s"
          % (d["singleton_tags"], d["singleton_ratio"] * 100,
             SINGLETON_WARN * 100, "健康" if d["healthy"] else "🔴 超标"))
    print("  ≥5 次的标签   : %d" % d["tags_ge5"])
    print("  拼写变体组    : %d（涉及 %d 次引用）"
          % (d["variant_groups"], d["variant_wasted_refs"]))
    print("  页面数        : %d" % d["pages"])
    print("\n  各层分布：")
    for k, v in d["by_type"].items():
        print("    %-10s 不同 %4d   引用 %4d" % (k, v["distinct"], v["refs"]))
    if not d["healthy"]:
        print("\n  ⚠️ 一次性标签占比超过 %.0f%%。见 wiki/tags.md 第二节的命名规则。"
              % (SINGLETON_WARN * 100))
        print("     跑 --suggest 看可机械合并的组；跑 --lowuse 2 看最该回退正文的标签。")
    return 0


if __name__ == "__main__":
    K.console_encoding()
    sys.exit(main())
